/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Exports
 *   Types: ReviewEntryComparison
 *   Functions: reviewOnlyLookupPath, isEntryListPath, bylineJoinPhrase, reviewEntryAgrees,
 *              compareReviewEntries, reviewMemberStates, reviewAlbumState, addsDatePrecision, reviewIdentityKey
 *   Constants: REVIEW_LOOKUP_LIMITS
 * Internal
 *   Functions: isRecord, list, fold
 * @end-catalog */

/**
 * Pure comparison rules for applying metadata lookup values to an existing-Album review (lookupValueApplication.ts applies them):
 * which paths only a review takes, when a lookup Artist entry agrees with a saved one, how a saved entry list compares with a
 * candidate's (the same, extended by entries appended after it, or different), what the review's capture says each list may
 * receive, and whether a lookup date only adds precision. No database, no lookup record. Every function is total on malformed
 * stored shapes.
 */
import { storedJoinPhrase } from '../../models/catalogCredit';
import { keepableMusicBrainzId } from '../../utils/musicBrainzId';
import { foldImportName, type ImportArtistEntry } from '../import/adminImportDraft';
import type { AdminImportDocument } from '../import/adminImportService';

/**
 * Review bounds: distinct Artist identities across the Album's and every member's lookup entries, and conflict answers per request
 * (the six Album paths, expected tracklist included, and four per member).
 */
export const REVIEW_LOOKUP_LIMITS = Object.freeze({ identities: 512, answers: 6 + 4 * 100 });
/** The value paths lookup supplies only to a review: the Album's expected tracklist and each member's track Artist entries. */
export const reviewOnlyLookupPath = (path: string) => path === 'album.expectedTracklist' || /^tracks\.[^.]+\.artists$/.test(path);
/** Artist entry lists: the Album's and, in a review, each member's. */
export const isEntryListPath = (path: string) => path === 'album.artists' || /^tracks\.[^.]+\.artists$/.test(path);
/** A join phrase as a byline presents it: a missing or invalid one reads as `, `. */
export const bylineJoinPhrase = (phrase: unknown): string => (typeof phrase === 'string' ? storedJoinPhrase(phrase) : undefined) ?? ', ';

const isRecord = (value: unknown): value is Record<string, unknown> => Boolean(value) && typeof value === 'object' && !Array.isArray(value);
const list = (value: unknown): unknown[] => Array.isArray(value) ? value : [];
const fold = (value: string) => foldImportName(value.trim());

/**
 * Whether a lookup entry names the Artist a saved entry shows: the same role, and the saved entry's Artist keeps the lookup entry's
 * MusicBrainz ID, or the saved name equals, case-insensitively, the lookup name or a credited name, canonical name or alias the run
 * found for the lookup entry's ID (`found`). A saved entry keeping another ID still agrees by name: its Artist keeps that ID unless
 * the administrator replaces it (an ID conflict), so the entry keeps its Artist.
 */
export function reviewEntryAgrees(saved: ImportArtistEntry, lookup: Pick<ImportArtistEntry, 'name' | 'role' | 'musicBrainzId'>, found: ReadonlyMap<string, readonly string[]>): boolean {
    if (!isRecord(saved) || !isRecord(lookup) || typeof saved.name !== 'string' || typeof lookup.name !== 'string' || saved.role !== lookup.role) return false;
    const mine = keepableMusicBrainzId(saved.musicBrainzId), theirs = keepableMusicBrainzId(lookup.musicBrainzId);
    if (mine !== null && mine === theirs) return true;
    const name = fold(saved.name);
    return name === fold(lookup.name) || (theirs !== null && (found.get(theirs) ?? []).some(other => typeof other === 'string' && fold(other) === name));
}

/** The outcome of compareReviewEntries; `append` carries the merged list. */
export type ReviewEntryComparison = { kind: 'same' } | { kind: 'append'; value: ImportArtistEntry[] } | { kind: 'differs' };
/**
 * How a candidate's entry list compares with the saved one. `same`: as many entries, each agreeing at its position, with the same
 * byline join phrases between them (the last entry's ignored). `append` (only with `options.append`): every saved entry agrees in
 * order and the candidate only adds entries after them; `value` is the saved entries (their keys, names and roles; a saved entry
 * without a MusicBrainz ID takes its lookup entry's while no other entry carries it), the last one taking the candidate's
 * connecting phrase, then the added entries as the candidate gives them. `differs`: anything else, including a saved list holding
 * two names that are equal case-insensitively, which no entry list may hold.
 */
export function compareReviewEntries(saved: readonly ImportArtistEntry[], lookup: readonly ImportArtistEntry[],
    options: { found: ReadonlyMap<string, readonly string[]>; append: boolean }): ReviewEntryComparison {
    const differs: ReviewEntryComparison = { kind: 'differs' };
    if (!Array.isArray(saved) || !Array.isArray(lookup) || !saved.every(entry => isRecord(entry) && typeof entry.name === 'string')) return differs;
    const names = saved.map(entry => fold(entry.name)), count = saved.length;
    if (new Set(names).size !== names.length || lookup.length < count || (!options.append && lookup.length !== count)) return differs;
    for (let index = 0; index < count; index++) {
        if (!reviewEntryAgrees(saved[index], lookup[index], options.found)) return differs;
        if (index < count - 1 && bylineJoinPhrase(saved[index].joinPhrase) !== bylineJoinPhrase(lookup[index].joinPhrase)) return differs;
    }
    if (lookup.length === count) return { kind: 'same' };
    const added = lookup.slice(count);
    const carried = new Set([...saved, ...added].map(entry => keepableMusicBrainzId(entry.musicBrainzId)).filter((id): id is string => id !== null));
    const value = saved.map((entry, index): ImportArtistEntry => {
        let musicBrainzId = keepableMusicBrainzId(entry.musicBrainzId);
        const offered = keepableMusicBrainzId(lookup[index].musicBrainzId);
        if (musicBrainzId === null && offered !== null && !carried.has(offered)) { musicBrainzId = offered; carried.add(offered); }
        return { key: entry.key, name: entry.name, role: entry.role, joinPhrase: index === count - 1 ? lookup[index].joinPhrase : entry.joinPhrase, musicBrainzId };
    });
    return { kind: 'append', value: [...value, ...added.map(entry => ({ ...entry }))] };
}

/**
 * What a review's capture says of each member (by slot): `complete` when its Credits were readable and the draft shows every
 * primary and featured Artist Credit, and `hasArtistCredit` when it has an Artist Credit of any role. A malformed capture, or a
 * member it lacks, is nothing complete.
 */
export function reviewMemberStates(doc: Pick<AdminImportDocument, 'catalogCapture'>): Map<string, { complete: boolean; hasArtistCredit: boolean }> {
    const states = new Map<string, { complete: boolean; hasArtistCredit: boolean }>(), capture: unknown = doc.catalogCapture;
    for (const member of list(isRecord(capture) ? capture.members : null)) {
        if (!isRecord(member) || typeof member.slotId !== 'string' || states.has(member.slotId)) continue;
        const credits = Array.isArray(member.credits) ? member.credits : null;
        states.set(member.slotId, { complete: credits !== null && member.artistsComplete === true,
            hasArtistCredit: credits !== null && credits.some(credit => isRecord(credit) && credit.subjectType === 'artist') });
    }
    return states;
}

/** Whether the review shows every primary and featured Artist Credit of the Album (`artists`) and whether its label may change (`label`). */
export function reviewAlbumState(doc: Pick<AdminImportDocument, 'catalogCapture'>): { artists: boolean; label: boolean } {
    const capture: unknown = doc.catalogCapture, album = isRecord(capture) && isRecord(capture.album) ? capture.album : null;
    return { artists: album?.artistsComplete === true, label: album?.label === 'none' || album?.label === 'first' };
}

/** Whether a lookup date only adds precision to the saved one: the same year and month gaining a month or day. */
export function addsDatePrecision(saved: unknown, lookup: unknown): boolean {
    if (!isRecord(saved) || !isRecord(lookup) || !Number.isSafeInteger(saved.year) || saved.year !== lookup.year) return false;
    if (saved.month === null) return lookup.month !== null && lookup.month !== undefined;
    return saved.month === lookup.month && saved.day === null && lookup.day !== null && lookup.day !== undefined;
}

/** The identity an entry counts as toward the review bound: its MusicBrainz ID, else its case-folded name. */
export const reviewIdentityKey = (entry: { name: string; musicBrainzId: string | null }) =>
    entry.musicBrainzId ? `id:${entry.musicBrainzId}` : `name:${foldImportName(entry.name)}`;
